local ServiceProviderCreator = require(script.Parent.ServiceProviderCreator)
local ServiceDescriptor = require(script.Parent.ServiceDescriptor)
local ServiceLifetime = require(script.Parent.ServiceLifetime)
local ServiceCollection = require(script.Parent.ServiceCollection)

return function()
	describe("ServiceProviderCreator", function()
		it("should create a new instance", function()
			local creator = ServiceProviderCreator.new({ IsLuaTypeProvider = true })
			expect(creator).to.be.ok()
			expect(creator.Services).to.be.ok()
		end)

		it("should build a ServiceProvider", function()
			local creator = ServiceProviderCreator.new({ IsLuaTypeProvider = true })
			local provider = creator:Build()

			expect(provider).to.be.ok()
			expect(provider.GetService).to.be.a("function")
		end)

		it("should validate descriptors during build", function()
			expect(function()
				local creator = ServiceProviderCreator.new({ IsLuaTypeProvider = true })
				creator:Register(ServiceDescriptor.new("InvalidService"))
			end).to.throw()
		end)
	end)
end
